ee:message.ee:set-payload:
%dw 2.0
output application/json
fun vacBystate(state) = (payload filter(($.state == state as String) and ($.case_type == "vaccinated")) map {
	count: $.count default 0
}
)[0]
---
((payload groupBy($.state) mapObject{
	caseReports:{
		state: $$,
		reports:
		{
			total: (($.count reduce ($ + $$) default 0) - (vacBystate($$).count as Number default 0)),
			($ orderBy($.case_type) map {
				($.case_type): ($.count),
				
			})
		}
	}
}).*caseReports) default[]
